boolean isForbiddenType(ContentType type) {
    String fullType = type.toString(false);

    for (String _type : BLACKLISTED_CONTENT_TYPES) {
      if (_type.equalsIgnoreCase(fullType)) {
        return true;
      }
    }

    return false;
  }
